diff.code:
// strictFunctionTypes: true
interface EventBus {
  // method shorthand
  on(handler: (e: AppEvent) => void): void;
  subscribers: ((e: AppEvent) => void)[];
}

// AppEvent is the base; ClickEvent extends AppEvent with .button
declare const bus: EventBus;
bus.on((e: ClickEvent) => e.button); // accepted
function addAll(target: ((e: AppEvent) => void)[], more: ((e: ClickEvent) => void)[]) {
  more.forEach(h => target.push(h));
}
